const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;

const ambient = new THREE.AmbientLight(0x7f8aa6, 0.5);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
keyLight.position.set(5, 8, 6);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
scene.add(keyLight);

const pointLight = new THREE.PointLight(0xff9f43, 1.8, 25);
pointLight.position.set(3, 4, 3);
pointLight.castShadow = true;
scene.add(pointLight);

const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(20, 20),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.95, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.5;
floor.receiveShadow = true;
scene.add(floor);

const cube = new THREE.Mesh(
  new THREE.BoxGeometry(1.6, 1.6, 1.6),
  new THREE.MeshStandardMaterial({ color: 0xe63946, roughness: 0.35, metalness: 0.1 })
);
cube.castShadow = true;
cube.receiveShadow = true;
scene.add(cube);

camera.position.set(3, 2, 4);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  cube.rotation.x = t * 0.2;
  cube.rotation.y = t * 0.35;
  controls.update();
  renderer.render(scene, camera);
}
animate();

